const SENTINEL_MARKER_KEY = '_gsd_sentinel_marker';

// --- n8n wrapper: Build Discovery Response -- D-07's DATA body (not the ack-only shape
// D-70-07 imposed on the enrichment/ingest lanes -- those two carry row outcomes for
// writes and had to stop reporting them on the wire; this lane writes nothing and its
// whole product is the list it returns). Folds by company_id so a Merge that fires
// twice under v1 can never duplicate a company (Task 3 Test 5); reads run_id off ANY
// item (marker or real) but excludes a D-70-23 gated sentinel's marker from the
// `companies` array itself -- a positive identity check (company_id presence), the
// same philosophy D-70-25's `hasRowIdentity` uses, adapted for this lane's flat
// per-company-item shape (Task 3 Test 6).
const byId = new Map();
let runId = null;
for (const it of $input.all()) {
  const row = it.json || {};
  if (row.run_id != null && runId == null) runId = row.run_id;
  const isMarker = row[SENTINEL_MARKER_KEY] === true;
  if (isMarker || row.company_id == null) continue;
  if (!byId.has(row.company_id)) {
    byId.set(row.company_id, {
      company_id: row.company_id,
      num_associated_contacts: row.num_associated_contacts ?? null,
      people: row.people || [],
      search_diagnostics: row.search_diagnostics ?? null,
    });
  }
}
return [{ json: { run_id: runId, companies: Array.from(byId.values()) } }];

// All Gap Sentinel — Phase 70 Plan 03 starved-lane sentinel.
// Bypasses the real routing chain entirely: see _add_starved_lane_sentinel's docstring.
const rows = $input.all().map((it) => it.json);
if (rows.length > 0 && rows.every((r) => r.gap === true)) return [{}]; return [];

// Sentinel Gate — Phase 70 Plan 10 (D-70-23). Fed ONLY by its condition
// node's own output. That output can be an empty array while the condition
// node itself still RAN (it is always fed the real lane's row set), and the
// engine counts a zero-item OUTPUT as a real delivery to whatever it feeds
// (executions 12204-12206) — sharing a Merge input directly with the
// condition node therefore let an empty verdict pre-empt a real row. This
// gate is what the condition feeds instead: when the condition emits
// nothing, the gate itself is fed zero items and — per the engine's OWN
// other rule (execution 12200: a node fed zero items does not run) — never
// runs, making no delivery at all. Only the condition's one marker item ever
// reaches this gate, so it always runs it becomes the delivery.
return $input.all().map((it) => ({ json: { ...it.json, '_gsd_sentinel_marker': true } }));

